#include <algorithm>
#include <cmath>
#include <limits>
#include <cstring>
#include <cassert>
#include <iostream>
#include <string>
double incoming;
bool ReadBinaryProperty(const std::wstring&,const std::wstring&,void* p,size_t n){assert(n==sizeof(double)); std::memcpy(p,&incoming,n); return true;}
template<class T> struct Setting { T m_value=-1,m_min=0,m_max=1; std::wstring m_section,m_entry; void ReadPersistedProperty(); };
template <> void Setting<double>::ReadPersistedProperty()
{
    const double def = m_value;
    ReadBinaryProperty(m_section, m_entry, &m_value, sizeof(double));
    if (m_value != def && m_min != m_max) m_value = std::clamp(m_value, m_min, m_max);
}
int main(){int checks=0; for(double value:{-2.,0.,0.5,1.,2.,-1.,std::numeric_limits<double>::infinity(),-std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){Setting<double> setting; incoming=value; setting.ReadPersistedProperty(); if(std::isnan(value))assert(std::isnan(setting.m_value)); else if(value==-1.)assert(setting.m_value==-1.); else assert(setting.m_value==std::clamp(value,0.,1.)); ++checks;}std::cout<<checks<<" controls passed; NaN survives; default sentinel preserved\n";}
